shots.draw_js:
clearScene();setBig(null);
setEq("$$\\hat V(s;w)=x(s)^{\\top}w \\qquad x(\\cdot)\\ \\text{is yours to choose}$$","top");
note("这组基得你自己给",640,310,"r lg");
setCap("L5 全程假定 x(s) 已经有了。<b>可是它从哪来？</b>");

clearScene();setEq(null);
setBig("特征不够就多加几个","多项式、傅里叶、瓦片编码，堆上去就是了");
setCap("「加特征」确实能降低 min MSVE —— <b>代价藏在维数里</b>。");

clearScene();setBig(null);
setEq("$$V^{\\pi}\\notin \\mathrm{span}\\{x_1,\\ldots,x_d\\} \\;\\Longrightarrow\\; \\min_w \\mathrm{MSVE}>0$$","top");
note("这个下界你测不到",640,310,"r lg");
setCap("真值不在张成里时，<b>误差有一个你无法通过训练消掉的下界</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[1000,10000],
  x:380,y:430,w:520,h:170,max:11000,
  label:function(i){return ["d=3 维","d=4 维"][i];},
  cls:function(i){return i===1?"r":"b";},
  fmt:function(v){return String(v);}});
note("每维取 10 格",640,466,"y");
setCap("网格式特征：<b>每多一维乘 10</b>。d=1→10、d=2→100、d=3→1000、d=4→10000。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"猜对基",sub:"min MSVE 才小",state:"on"},
  {label:"猜不对就堆",sub:"特征数 10^d",state:"dead"},
  {label:"而且测不到",sub:"不知道离最好多远",state:"dead"}]});
note("这才是要学表示的理由",640,420,"y");
setCap("<b>指名反驳</b>：问题不是「几个特征」，是<b>你得先猜对那组基</b>。");

clearScene();setBig(null);setEq(null);
note("不用预先选基",640,280,"g lg");
note("k-NN · 核回归",640,350,"b lg");
setCap("非参数方法绕开了上一集的问题：<b>它不要求你先猜出一组基</b>。");

clearScene();setEq(null);
setBig("更灵活所以更好","不用选基，表达能力还随数据增长");
setCap("它确实<b>更安全</b>，而且是有定理的安全。<b>但它撞的是另一堵墙。</b>");

clearScene();setBig(null);
setEq("$$\\text{averager} \\;\\Longrightarrow\\; \\lVert \\Pi V-\\Pi V'\\rVert_\\infty\\le\\lVert V-V'\\rVert_\\infty$$","top");
note("在 sup 范数下非扩张",640,300,"g lg");
note("于是 Π∘B 仍是压缩",640,360,"g lg");
setCap("<b>averager</b>：输出是输入的凸组合，因而在 <b>sup 范数</b>下非扩张。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[1000,10000],
  x:380,y:430,w:520,h:170,max:11000,
  label:function(i){return ["d=3 维","d=4 维"][i];},
  cls:function(i){return i===1?"r":"v";},
  fmt:function(v){return String(v);}});
note("覆盖所需的点数",640,466,"r");
setCap("覆盖 d 维所需的点数<b>还是 10^d</b>：d=3 要 1000 个，d=4 要 10000 个。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"稳定性",sub:"有定理保证",state:"on"},
  {label:"表达能力",sub:"随数据增长",state:"on"},
  {label:"可扩展性",sub:"覆盖要 10^d 个点",state:"dead"}]});
note("换了一堵墙，更硬",640,420,"r");
setCap("<b>指名反驳</b>：它确实更安全 —— <b>代价是它要的数据量拿不到</b>。");

clearScene();setBig(null);setEq(null);
note("输入是一整屏像素",640,280,"b lg");
note("1000 × 1000",640,350,"y lg");
setCap("深度网络把「选基」变成「学基」。但直接接全连接层，<b>参数会爆</b>。");

clearScene();setEq(null);
setBig("CNN 更聪明","它像视觉皮层，所以更懂图像");
setCap("类比很好听，但它解释不了<b>为什么参数会少四万倍</b>。");

clearScene();setBig(null);
setEq("$$\\text{fully connected: } 1000\\times 1000 = 10^6 \\ \\text{weights per unit}$$","top");
note("每个单元 10⁶ 个权重",640,310,"r lg");
setCap("全连接：<b>一个</b>隐层单元就要 10⁶ 个权重。而你需要很多个单元。");

clearScene();setBig(null);setEq(null);
note("参数共享",400,290,"g lg");
note("平移不变性",880,290,"g lg");
note("同一件事的两面",640,400,"y lg");
setCap("共享权重<b>顺带</b>白送了平移不变性 —— 不是额外设计，是同一个约束。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"10⁶ → 25",sub:"四万倍",state:"on"},
  {label:"白送不变性",sub:"同一个约束",state:"on"},
  {label:"前提",sub:"位置无关才成立",state:"dead"}]});
note("这是关于图像的假设",640,420,"y");
setCap("<b>指名反驳</b>：CNN 不是更聪明，它是一个<b>关于图像结构的假设</b>。");
